sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {


	if(current.getValue('hr_service') == "b745a0501b53ac10ea0eda02dd4bcb4b") //Refusal of dangerous work
	{
		template.print("Refusal of dangerous work");
	}
	if(current.getValue('hr_service')== "5227b08f2f4b60d04cbeb1e72799b659") //Internal Safety Complaint
	{
	template.print("Internal Safety Complaint");
	}

	if(current.getValue('hr_service')== "6a2b1ada2f4f2c904cbeb1e72799b6ae") //Employee Workplace Incident Reporting
	{
		template.print("Employee Workplace Incident Reporting");
	}

})(current, template, email, email_action, event);
